class Solution {
  // best path of the child starting at (0, n-1), staying strictly above the diagonal
  private static int upper(int[][] f, int n) {
    int NEG = Integer.MIN_VALUE / 2;
    int[] dp = new int[n + 2];
    java.util.Arrays.fill(dp, NEG);
    dp[n - 1] = f[0][n - 1];
    for (int i = 1; i <= n - 2; i++) {
      int[] nd = new int[n + 2];
      java.util.Arrays.fill(nd, NEG);
      for (int j = i + 1; j < n; j++) {
        int best = Math.max(dp[j], Math.max(dp[j + 1], j - 1 > i - 1 ? dp[j - 1] : NEG));
        if (best > NEG) nd[j] = best + f[i][j];
      }
      dp = nd;
    }
    return dp[n - 1];
  }

  public int maxCollectedFruits(int[][] fruits) {
    int n = fruits.length, total = 0;
    for (int i = 0; i < n; i++) total += fruits[i][i];
    total += upper(fruits, n);
    for (int i = 0; i < n; i++) {
      for (int j = i + 1; j < n; j++) {
        int tmp = fruits[i][j];
        fruits[i][j] = fruits[j][i];
        fruits[j][i] = tmp;
      }
    }
    return total + upper(fruits, n);
  }
}
